          ]
        }
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Condition/condition-2",
      "resource": {
        "resourceType": "Condition",
        "id": "condition-2",
        "subject": {
          "reference": "Patient/patient-1"
        },
        "code": {
          "text": "Chronic psychosis, partially symptomatic by history; off antipsychotics for more than 6 months"
        },
        "clinicalStatus": {
          "coding": [
            {
              "system": "http://terminology.hl7.org/CodeSystem/condition-clinical",
              "code": "active"
            }
          ]
        }
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Condition/condition-3",
      "resource": {
        "resourceType": "Condition",
        "id": "condition-3",
        "subject": {
          "reference": "Patient/patient-1"
        },
        "code": {
          "text": "Personality disorder, type unspecified; reported past diagnosis"
        }
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Condition/condition-4",
      "resource": {
        "resourceType": "Condition",
        "id": "condition-4",
        "subject": {
          "reference": "Patient/patient-1"
        },
        "code": {
          "text": "Chronic insomnia"
        },
        "clinicalStatus": {
          "coding": [
            {
              "system": "http://terminology.hl7.org/CodeSystem/condition-clinical",
              "code": "active"
            }
          ]
        }
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Condition/condition-5",
      "resource": {
        "resourceType": "Condition",
        "id": "condition-5",
        "subject": {
          "reference": "Patient/patient-1"
        },
        "code": {
          "text": "Psychosocial stressors, including unstable housing"
        },
        "clinicalStatus": {
          "coding": [
            {
              "system": "http://terminology.hl7.org/CodeSystem/condition-clinical",
              "code": "active"
            }
          ]
        }
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-1",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-1",
        "status": "final",
        "code": {
          "text": "Benzodiazepine withdrawal symptoms when without benzodiazepines"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Reports feeling very edgy, unable to sleep, sick, and sweaty when without benzodiazepines."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-2",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-2",
        "status": "final",
        "code": {
          "text": "History of withdrawal seizures"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No history of withdrawal seizures."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-3",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-3",
        "status": "final",
        "code": {
          "text": "Psychosis symptoms by patient report"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "History of voices and paranoia. Voices come and go and are currently described as not too bad; background voices reported."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-4",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-4",
        "status": "final",
        "code": {
          "text": "Suicidal and homicidal ideation"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No current suicidal or homicidal ideation."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-5",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-5",
        "status": "final",
        "code": {
          "text": "Alcohol use"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Reports social alcohol use 1–2 times per week, 3–4 drinks; denies alcohol dependence and heavy alcohol use."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-6",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-6",
        "status": "final",
        "code": {
          "text": "Other substance use"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Denies current use of other illicit drugs; reports past occasional cannabis use. Denies intravenous drug use."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-7",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-7",
        "status": "final",
        "code": {
          "text": "Sleep and work functioning"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Reports chronic poor sleep, worse when trying to reduce benzodiazepines, and missing casual work shifts due to poor sleep and 'benzo hangover'."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationStatement/medication-statement-1",
      "resource": {
        "resourceType": "MedicationStatement",
        "id": "medication-statement-1",
        "status": "active",
        "medicationCodeableConcept": {
          "text": "Diazepam (including benzodiazepines reported as diazepam equivalents)"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosage": [
          {
            "text": "Reports using daily, from prescriptions and friends; estimated 20–30 mg diazepam equivalent on most days for the last 12–18 months, to switch off thoughts and for sleep."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationStatement/medication-statement-2",
      "resource": {
        "resourceType": "MedicationStatement",
        "id": "medication-statement-2",
        "status": "stopped",
        "medicationCodeableConcept": {
          "text": "Olanzapine"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "note": [
          {
            "text": "Patient thinks they were previously taking olanzapine and reports stopping about 6 months ago due to weight gain and sedation. No current antipsychotic."
          }
        ]
      }
    }
  ]
}
